import type { MessageDescriptor } from '@lingui/core'
import { msg } from '@lingui/core/macro'
import { useLingui } from '@lingui/react'
import { Link, type LinkProps, useMatchRoute } from '@tanstack/react-router'
import { ArrowLeftIcon, type LucideIcon } from 'lucide-react'
import { type ReactNode, createContext, useContext } from 'react'
import { AccountMenu } from '#/components/identity/account-menu.tsx'
import { Button } from '#/components/ui/button.tsx'
import { Separator } from '#/components/ui/separator.tsx'
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarTrigger,
} from '#/components/ui/sidebar.tsx'
import { LinkExternal } from '#/components/utils/link-external.tsx'
import { ShortLinkTitle } from '#/components/utils/link-title.tsx'
import { useCustomizationData } from '#/contexts/customization.tsx'
import { LocaleSelector } from '#/locales/locale-selector.tsx'

export type AccountShellTarget = Pick<LinkProps, 'to' | 'params'>

export type AccountShellLink = AccountShellTarget & {
  title: string | MessageDescriptor
  description?: string | MessageDescriptor
  Icon?: LucideIcon
}

export type AccountShellProps = {
  title?: string | MessageDescriptor
  /** The account home, and the target of the mobile back button. */
  base: AccountShellTarget
  links: ReadonlyArray<AccountShellLink>
  children?: ReactNode
  prepend?: ReactNode
}

const navigationLabel = msg`Navigation`
const backLabel = msg`Back`

const AccountShellLinksContext = createContext<readonly AccountShellLink[]>([])

/**
 * The shell's navigation entries, for pages that want to present them as
 * content rather than chrome — the account home page lists them as a directory.
 *
 * Exposed through context rather than threaded as props: the pages are mounted
 * by TanStack Router as `component: () => <Page />`, so there is no prop path
 * from the route that builds the links down to the page that renders them.
 */
export function useAccountShellLinks(): readonly AccountShellLink[] {
  return useContext(AccountShellLinksContext)
}

/**
 * Tests whether a navigation target is the page currently being shown.
 *
 * @NOTE `to` is a path *template* (`/account/u/$accountId/manage`), so it never
 * equals the resolved pathname — the comparison has to go through the router.
 */
export function useIsCurrentTarget(): (target: AccountShellTarget) => boolean {
  const matchRoute = useMatchRoute()
  return ({ to, params }) => to != null && matchRoute({ to, params }) !== false
}

/**
 * Account-manager frame: `SidebarProvider` + `Sidebar` + `SidebarInset`, with
 * `SidebarTrigger` in the inset header — a composition that brings the
 * collapsible rail, the mobile sheet, the keyboard shortcut and the persisted
 * open/closed state with it.
 *
 * @NOTE This owns the whole page frame, including its own `<title>`. The app
 * title must be the one that takes effect, and React hoists every `<title>`
 * into the head with the last one rendered winning.
 */
export function AccountShell({
  children,
  title,
  base,
  links,
  prepend,
}: AccountShellProps) {
  const { _ } = useLingui()
  const isCurrent = useIsCurrentTarget()
  const { logo, name, links: footerLinks } = useCustomizationData()

  const atBase = isCurrent(base)
  const titleString = typeof title === 'object' ? _(title) : (title ?? name)

  const currentLink = links.find(isCurrent)
  const pageTitle = currentLink?.title
  const pageTitleStr = typeof pageTitle === 'object' ? _(pageTitle) : pageTitle

  return (
    <AccountShellLinksContext value={links}>
      <SidebarProvider>
        {titleString && <title>{titleString}</title>}

        <Sidebar collapsible="offcanvas">
          <SidebarHeader>
            {/* @NOTE A SidebarMenuButton rather than a bare div, so the brand
            row shares the nav items' geometry. `render={<div/>}` keeps it
            non-interactive — there is nowhere to navigate to. */}
            <SidebarMenu>
              <SidebarMenuItem>
                <SidebarMenuButton
                  className="data-[slot=sidebar-menu-button]:p-1.5!"
                  render={<div />}
                >
                  {logo && (
                    <img
                      src={logo}
                      alt={name || _(msg`Logo`)}
                      className="h-5! w-auto max-w-24 shrink-0 object-contain"
                    />
                  )}
                  <span className="text-base font-semibold">
                    {titleString ?? name}
                  </span>
                </SidebarMenuButton>
              </SidebarMenuItem>
            </SidebarMenu>
          </SidebarHeader>

          <SidebarContent>
            <SidebarGroup>
              <SidebarGroupContent className="flex flex-col gap-2">
                {/* @NOTE gap-1 overrides SidebarMenu's gap-0: without it an
                active row and a hovered row next to it merge into one block. */}
                <SidebarMenu className="gap-1">
                  {links.map((link) => (
                    <SidebarMenuItem key={link.to}>
                      <SidebarMenuButton
                        isActive={link === currentLink}
                        // @NOTE The style bolds the active row; the background
                        // alone is enough to mark the current page.
                        // Taller rows with 16px text: the sidebar is the
                        // phone's main navigation once it slides in.
                        className="h-10 gap-3 px-3 text-base data-active:font-normal [&_svg]:size-5"
                        tooltip={
                          typeof link.title === 'object'
                            ? _(link.title)
                            : link.title
                        }
                        render={
                          // @NOTE `exact` because the account home is the
                          // parent route of every other entry: without it,
                          // Link marks "Home" as the current page throughout.
                          <Link
                            to={link.to}
                            params={link.params}
                            activeOptions={{ exact: true }}
                          >
                            {link.Icon && <link.Icon aria-hidden />}
                            <span>
                              {typeof link.title === 'object'
                                ? _(link.title)
                                : link.title}
                            </span>
                          </Link>
                        }
                      />
                    </SidebarMenuItem>
                  ))}
                </SidebarMenu>
              </SidebarGroupContent>
            </SidebarGroup>

            {/* @NOTE `mt-auto` pins the deployment's links to the bottom of the
            sidebar, directly above the user nav. */}
            {footerLinks && footerLinks.length > 0 && (
              <SidebarGroup className="mt-auto">
                <SidebarGroupContent>
                  <SidebarMenu className="gap-1">
                    {footerLinks.map((link) => (
                      <SidebarMenuItem key={link.href}>
                        <SidebarMenuButton
                          className="h-9 px-3 text-sm"
                          render={
                            <LinkExternal href={link.href} rel={link.rel} />
                          }
                        >
                          <span>
                            <ShortLinkTitle link={link} />
                          </span>
                        </SidebarMenuButton>
                      </SidebarMenuItem>
                    ))}
                  </SidebarMenu>
                </SidebarGroupContent>
              </SidebarGroup>
            )}
          </SidebarContent>

          <SidebarFooter>
            <LocaleSelector className="w-full" />
            <AccountMenu />
          </SidebarFooter>
        </Sidebar>

        <SidebarInset>
          <header className="bg-background sticky top-0 z-40 flex h-14 shrink-0 items-center gap-2 border-b px-4">
            {/* @NOTE On a sub-page the mobile header drills back to the account
            home instead of opening the sidebar; the trigger stays on desktop,
            where the sidebar is always reachable. */}
            {!atBase && (
              <Button
                variant="ghost"
                size="icon"
                className="-ml-1 md:hidden"
                aria-label={_(backLabel)}
                render={
                  <Link
                    to={base.to}
                    params={base.params}
                    activeOptions={{ exact: true }}
                  />
                }
              >
                <ArrowLeftIcon />
              </Button>
            )}
            {/* @NOTE SidebarTrigger's sr-only text is hardcoded English; the
            aria-label translates it without forking the primitive. */}
            <SidebarTrigger
              aria-label={_(navigationLabel)}
              className={atBase ? undefined : 'max-md:hidden'}
            />
            {/* @NOTE self-center overrides the primitive's `self-stretch`,
            which with a definite `h-4` pins the line to the top instead. */}
            <Separator
              orientation="vertical"
              className="mr-2 data-vertical:h-4 data-vertical:self-center"
            />
            {pageTitleStr && (
              <h2 className="text-lg font-semibold">{pageTitleStr}</h2>
            )}
            {/* @NOTE On desktop the sidebar keeps the brand in view; on mobile
            it is closed, so the header carries it instead. */}
            {(logo || name) && (
              <div className="ml-auto flex min-w-0 items-center gap-2 md:hidden">
                {logo && (
                  <img
                    src={logo}
                    alt={name || _(msg`Logo`)}
                    className="h-5 w-auto max-w-24 shrink-0 object-contain"
                  />
                )}
                {name && (
                  <span className="truncate text-sm font-medium">{name}</span>
                )}
              </div>
            )}
          </header>

          {prepend}

          <main
            className="mx-auto flex w-full max-w-4xl min-w-0 flex-col gap-4 p-4 md:p-6"
            role="main"
          >
            {children}
          </main>
        </SidebarInset>
      </SidebarProvider>
    </AccountShellLinksContext>
  )
}

import { Trans, useLingui } from '@lingui/react/macro'
import { type LucideIcon, SearchIcon } from 'lucide-react'
import { Fragment, type ReactNode, useMemo, useState } from 'react'
import { FieldInput } from '#/components/forms/fields/text-field.tsx'
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
} from '#/components/ui/empty.tsx'
import { Separator } from '#/components/ui/separator.tsx'
import { Skeleton } from '#/components/ui/skeleton.tsx'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table.tsx'
import { cn } from '#/lib/utils.ts'

export type SessionListColumn<T> = {
  /** Column heading. Rendered visually and as the row's `<th>` scope. */
  header: ReactNode
  /** Cell contents for one row. */
  cell: (item: T) => ReactNode
  /** Tailwind width/alignment classes for both header and cells. */
  className?: string
  /** Type and colour for the cells, so the headings stay uniform. */
  cellClassName?: string
  /** Hidden below `md`, where the stacked layout takes over. */
  hideOnMobile?: boolean
}

export type SessionListProps<T> = {
  items: readonly T[]
  columns: ReadonlyArray<SessionListColumn<T>>
  /** Stable key per row. */
  rowKey: (item: T) => string
  /** Free-text haystack for the filter box, per row. */
  searchText: (item: T) => string
  /** Trailing action for the row — a button, usually. */
  action: (item: T) => ReactNode
  /** Row title for narrow screens. */
  mobileTitle: (item: T) => ReactNode
  /** Shown when the list itself is empty (before any filtering). */
  empty: ReactNode
  /** Illustrates the empty state — the page's own nav icon. */
  emptyIcon: LucideIcon
  filterLabel: string
  /**
   * Renders placeholder rows in place of the data. Owned by this component
   * rather than a separate skeleton so the two cannot drift apart — the
   * placeholder is built from the same `columns`, so it always has the right
   * number of columns at the right widths.
   */
  loading?: boolean
}

/** How many placeholder rows to draw while loading. */
const SKELETON_ROWS = 4

/**
 * Tabular list of sessions, for the connected-apps and devices pages.
 *
 * @NOTE Below `md` the table becomes one stacked row per session: a
 * four-column table at 390px either scrolls sideways or crushes every column.
 * The same data is rendered twice rather than scrolled, which is why `columns`
 * carries both `hideOnMobile` and a separate `mobileTitle`.
 */
export function SessionList<T>({
  items,
  columns,
  rowKey,
  searchText,
  action,
  mobileTitle,
  empty,
  emptyIcon: EmptyIcon,
  filterLabel,
  loading = false,
}: SessionListProps<T>) {
  const { t } = useLingui()
  const [query, setQuery] = useState('')

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!q) return items
    return items.filter((item) => searchText(item).toLowerCase().includes(q))
  }, [items, query, searchText])

  if (!loading && !items.length) {
    return (
      <Empty>
        <EmptyHeader>
          <EmptyMedia variant="icon">
            <EmptyIcon aria-hidden />
          </EmptyMedia>
          <EmptyDescription>{empty}</EmptyDescription>
        </EmptyHeader>
      </Empty>
    )
  }

  return (
    <div className="flex flex-col gap-4">
      {/* @NOTE Always shown, not gated on a row count. Hiding it below a
        threshold means it appears and disappears as sessions come and go, so
        nobody learns it is there — and the list length is exactly what you
        cannot predict. The early return above keeps it off an empty list. */}
      <div className="relative">
        <SearchIcon
          aria-hidden
          className="text-muted-foreground pointer-events-none absolute top-1/2 left-3 size-5 -translate-y-1/2"
        />
        <FieldInput
          type="search"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder={filterLabel}
          aria-label={filterLabel}
          className="pl-10"
        />
      </div>

      {/* Desktop: table */}
      <div className="hidden md:block">
        <Table>
          <TableHeader>
            <TableRow>
              {columns.map((column, index) => (
                <TableHead key={index} className={column.className}>
                  {column.header}
                </TableHead>
              ))}
              <TableHead className="w-0 text-right">
                <span className="sr-only">{t`Actions`}</span>
              </TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading &&
              Array.from({ length: SKELETON_ROWS }, (_, row) => (
                <TableRow key={`skeleton-${row}`}>
                  {columns.map((column, index) => (
                    <TableCell key={index} className={column.className}>
                      <Skeleton className="h-4 w-full max-w-[12rem]" />
                    </TableCell>
                  ))}
                  <TableCell className="text-right">
                    <Skeleton className="ml-auto h-8 w-20" />
                  </TableCell>
                </TableRow>
              ))}
            {!loading &&
              filtered.map((item) => (
                <TableRow key={rowKey(item)}>
                  {columns.map((column, index) => (
                    <TableCell
                      key={index}
                      className={cn(column.className, column.cellClassName)}
                    >
                      {column.cell(item)}
                    </TableCell>
                  ))}
                  <TableCell className="text-right">{action(item)}</TableCell>
                </TableRow>
              ))}
          </TableBody>
        </Table>
      </div>

      {/* @NOTE Mobile: one row per session. Not the registry's `Item`, whose
        `ItemDescription` is a line of text and whose row wraps — a labelled
        pair per column needs neither. */}
      <div className="flex flex-col md:hidden">
        {loading &&
          Array.from({ length: SKELETON_ROWS }, (_, row) => (
            <Fragment key={`skeleton-${row}`}>
              {row > 0 && <Separator />}
              <div className="flex flex-col gap-2 py-4">
                <div className="flex items-center justify-between gap-3">
                  <Skeleton className="h-5 w-40" />
                  <Skeleton className="h-8 w-20 shrink-0" />
                </div>
                <Skeleton className="h-4 w-full" />
                <Skeleton className="h-4 w-full" />
              </div>
            </Fragment>
          ))}
        {!loading &&
          filtered.map((item, index) => (
            <Fragment key={rowKey(item)}>
              {index > 0 && <Separator />}
              {/* Title and action share the first line; the labelled pairs
                run the full width underneath. */}
              <div className="flex flex-col gap-2 py-4">
                <div className="flex items-center justify-between gap-3">
                  <div className="min-w-0 flex-1 truncate text-base font-semibold">
                    {mobileTitle(item)}
                  </div>
                  <div className="shrink-0">{action(item)}</div>
                </div>
                <dl className="text-muted-foreground flex flex-col gap-1 text-sm">
                  {columns
                    .filter((column) => !column.hideOnMobile)
                    .map((column, index) => (
                      <div key={index} className="flex justify-between gap-4">
                        <dt className="shrink-0">{column.header}</dt>
                        <dd className="min-w-0 truncate text-right">
                          {column.cell(item)}
                        </dd>
                      </div>
                    ))}
                </dl>
              </div>
            </Fragment>
          ))}
      </div>

      {!loading && !filtered.length && (
        <p className="text-muted-foreground py-6 text-center text-sm">
          <Trans>No matches</Trans>
        </p>
      )}
    </div>
  )
}

